import React, { useRef, useState, useEffect, useId } from "react";

/**
 * LazySection — only mounts children once the placeholder scrolls into view.
 * Uses IntersectionObserver with a rootMargin so the section starts loading
 * slightly before the user reaches it (no visible pop-in).
 *
 * @param {string} minHeight  - Reserve space before mounting to prevent layout shift
 * @param {string} rootMargin - How far before viewport to start loading (default 300px)
 */
const LazySection = ({ children, minHeight = "200px", rootMargin = "300px" }) => {
  const ref = useRef(null);
  const uniqueId = useId();
  const cleanId = uniqueId.replace(/:/g, "");
  const className = `lazy-section-${cleanId}`;
  
  const [visible, setVisible] = useState(() => {
    if (typeof window !== "undefined") {
      if (window.__PRERENDERED__ || (window.navigator && window.navigator.userAgent && window.navigator.userAgent.includes("ReactSnap"))) {
        return true;
      }
    }
    return false;
  });

  const [hasMounted, setHasMounted] = useState(() => {
    if (typeof window !== "undefined") {
      if (window.__PRERENDERED__ || (window.navigator && window.navigator.userAgent && window.navigator.userAgent.includes("ReactSnap"))) {
        return true;
      }
    }
    return false;
  });

  useEffect(() => {
    if (visible) return;

    const el = ref.current;
    if (!el) return;

    // If IntersectionObserver is not supported, just show it immediately
    if (!window.IntersectionObserver) {
      setVisible(true);
      setHasMounted(true);
      return;
    }

    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting) {
          setVisible(true);
          // Small delay before setting hasMounted to trigger CSS transition
          setTimeout(() => {
            setHasMounted(true);
            // Refresh smooth scroll to account for new section height
            if (window.refreshSmoothScroll) {
              window.refreshSmoothScroll();
            }
          }, 50);
          observer.disconnect();
        }
      },
      { rootMargin }
    );

    observer.observe(el);
    return () => observer.disconnect();
  }, [rootMargin, visible]);

  return (
    <>
      <style>{`
        .${className} {
          min-height: ${visible ? "auto" : minHeight};
        }
      `}</style>
      <div
        ref={ref}
        className={`lazy-section ${hasMounted ? "is-mounted" : ""} ${className}`}
      >
        {visible ? children : null}
      </div>
    </>
  );
};

export default LazySection;
